style.css:
@-moz-document domain("biblegateway.com") {
/* --- Dark Mode Color Palette --- */
    :root {
        --bg-base: #121212;
        --bg-card: #1e1e1e;
        --border-color: #333333;
        --text-primary: #e0e0e0;
        --text-secondary: #aaaaaa;
        --accent-blue: #4a90e2;
        --accent-blue-hover: #73aaf2;
        --highlight-bg: #2c2c2c;
    }

    /* --- Main Page Structure --- */
    html, body, #wrap, #container, .site-wrap, 
    .passage-content, .passage-text, .twocol-right, 
    .passage-display--content, .yv-breadcrumb, .docked-search-bar, 
    article, section, .card, .panel, .well {
        background-color: var(--bg-card) !important;
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
    }

    body {
        background-color: var(--bg-base) !important;
    }

    /* --- Text Visibility --- */
    p, span, div, .text, .verse-num, .bcv {
        color: var(--text-primary) !important;
    }

    h1, h2, h3, h4, .chap-num, .passage-display--head, 
    .chap-nav h2, .passage-display--head h1 {
        color: #ffffff !important;
    }

    /* --- Sidebar & Navigation --- */
    .site-sidebar, #left-rail, .left-rail-container,
    #header, #docked-header, .site-header {
        background-color: var(--bg-card) !important;
        border-color: var(--border-color) !important;
    }

    .nav-list a, .nav-list span, #left-rail h3 {
        color: var(--text-secondary) !important;
    }

    .icon, .nav-list .icon {
        filter: brightness(0.8) invert(1) !important;
    }

    .nav-list a:hover, .nav-list a.active {
        background-color: var(--highlight-bg) !important;
        color: var(--text-primary) !important;
    }

    .logo {
        filter: brightness(0.5) invert(1) !important;
    }

    /* --- UI Elements & Buttons --- */
    .btn, .button, .tool-link, .passage-tools, .version-dropdown, #version-dd {
        background-color: var(--bg-card) !important;
        color: var(--text-secondary) !important;
        border: 1px solid var(--border-color) !important;
    }

    .btn:hover, .tool-link:hover {
        background-color: var(--highlight-bg) !important;
        color: var(--text-primary) !important;
    }

    .btn-primary, .cta-button {
        background-color: var(--accent-blue) !important;
        color: #ffffff !important;
        border: none !important;
    }

    /* --- Search & Inputs --- */
    .search-box-container, .form-control {
        background-color: var(--bg-base) !important;
        color: var(--text-primary) !important;
        border: 1px solid var(--border-color) !important;
    }

    input::placeholder { 
        color: var(--text-secondary) !important; 
    }

    /* --- Links --- */
    a, a:visited, .chap-link {
        color: var(--accent-blue) !important;
        text-decoration: none !important;
    }

    a:hover, .chap-link:hover {
        color: var(--accent-blue-hover) !important;
        text-decoration: underline !important;
    }
}
